import "server-only";

import sharp from "sharp";
import { getProductImageSrc } from "@/lib/product-image";
import { ImageCache } from "./image-cache";

// The widths generated by next/image's default responsive configuration.
const widths = new Set([32, 48, 64, 96, 128, 256, 384, 640, 750, 828, 1080, 1200, 1920, 2048, 3840]);
const headers = { "Cache-Control": "private, no-store" };
const MB = 1024 * 1024;

type Dependencies = {
  getImageKey: (productId: string) => Promise<string | null>;
  getStorageUrl: (imageKey: string) => Promise<string | null>;
  readImage: (imageKey: string) => Promise<Buffer | null>;
};

export function createProductImageHandler({ getImageKey, getStorageUrl, readImage }: Dependencies) {
  // Share original downloads between widths; bound memory and refresh replaced files.
  const originals = new ImageCache(24 * MB, 60_000);
  const variants = new ImageCache(40 * MB, 60_000);

  return async function serveProductImage(request: Request, productId: string): Promise<Response> {
    try {
      const requestedWidths = new URL(request.url).searchParams.getAll("w");
      const width = requestedWidths.length === 1 && /^\d+$/.test(requestedWidths[0])
        ? Number(requestedWidths[0]) : null;
      if (requestedWidths.length && (width === null || !widths.has(width))) {
        return new Response(null, { status: 400, headers });
      }

      // Always check current catalogue RLS, even when the image bytes are cached.
      const imageKey = await getImageKey(productId);
      if (!imageKey?.trim()) return new Response(null, { status: 404, headers });

      const local = getProductImageSrc(productId, imageKey);
      if (local?.startsWith("/images/")) {
        return new Response(null, { status: 307, headers: { ...headers, Location: new URL(local, request.url).href } });
      }

      if (width !== null) {
        const webp = /\bimage\/webp\b/i.test(request.headers.get("accept") ?? "");
        const format = webp ? "webp" : "png";
        try {
          const buffer = await variants.get(JSON.stringify([imageKey, width, format]), async () => {
            const source = await originals.get(imageKey, async () => {
              const image = await readImage(imageKey);
              if (!image) throw new Error("Product image unavailable.");
              return image;
            });
            const image = sharp(source, { limitInputPixels: 40_000_000 });
            const metadata = await image.metadata();
            if (!metadata.format || !["jpeg", "png", "webp", "avif"].includes(metadata.format) || (metadata.pages ?? 1) > 1) {
              throw new Error("Preserve original image format.");
            }
            // Preserve the full composition, transparency and orientation; CSS owns the crop.
            const resized = image.rotate().resize({ width, withoutEnlargement: true });
            return webp ? resized.webp({ quality: 85 }).toBuffer() : resized.png().toBuffer();
          });
          return new Response(new Uint8Array(buffer), {
            headers: { ...headers, "Content-Type": `image/${format}`, "Content-Length": String(buffer.length), Vary: "Accept", "X-Content-Type-Options": "nosniff" },
          });
        } catch {
          // A failed/unsupported transform must still display the existing original.
        }
      }

      const url = await getStorageUrl(imageKey);
      return url
        ? new Response(null, { status: 307, headers: { ...headers, Location: url } })
        : new Response(null, { status: 404, headers });
    } catch {
      // Provider errors can contain signed URLs; keep them out of logs/responses.
      return new Response(null, { status: 503, headers });
    }
  };
}
